-- blog_translations_20261007.sql — missing title/excerpt/summary/SEO editions of 5 published articles
-- Idempotent DATA script (not a migration, no schema change). Run it by hand in the Supabase SQL editor.
-- Every column is written ONLY when it is empty or still a verbatim copy of the English text, so a human
-- translation is never overwritten and re-running the script changes nothing the second time.
-- All non-English text was written in-session (no translation API) and NEEDS NATIVE REVIEW.
-- Generated 5 UPDATE statements; each should report 'UPDATE 1'.
begin;
update public.blog_posts set
  title_pl = case when title_pl is null or btrim(title_pl) = '' or title_pl = title_en then 'Rafineria Dangote rusza z największą w historii Afryki ofertą publiczną, celuje w 23 mld dolarów' else title_pl end,
  excerpt_pl = case when excerpt_pl is null or btrim(excerpt_pl) = '' or excerpt_pl = excerpt_en then 'Rafineria Aliko Dangote w Lagos rozpoczęła największą — jak ją reklamowano — sprzedaż akcji na kontynencie; przy pełnej subskrypcji spółka wyceniana jest na 65,22 biliona nair, a osobisty majątek Dangote zbliża się do 60 mld dolarów.' else excerpt_pl end,
  summary_pl = case when summary_pl is null or btrim(summary_pl) = '' or summary_pl = summary_en then 'Dangote Petroleum Refinery rozpoczęła największą w historii Afryki ofertę publiczną (IPO), mającą przynieść założycielowi Aliko Dangote 23 mld dolarów. Inwestorzy indywidualni mogą kupować akcje od 5250 nair do 13 października, a przy pełnej subskrypcji rafineria jest wyceniana na 65,22 biliona nair. Zakład, który przetwarza 700 000 baryłek dziennie i uczynił z Nigerii eksportera netto paliw, jest także trampoliną dla planowanego projektu energetycznego o wartości 17 mld dolarów w Lamu w Kenii.' else summary_pl end,
  seo_title_pl = case when seo_title_pl is null or btrim(seo_title_pl) = '' or seo_title_pl = seo_title_en then 'IPO rafinerii Dangote celuje w 23 mld dolarów w największej sprzedaży akcji w Afryce' else seo_title_pl end,
  seo_description_pl = case when seo_description_pl is null or btrim(seo_description_pl) = '' or seo_description_pl = seo_description_en then 'Rafineria Aliko Dangote w Lagos rozpoczęła największe w Afryce IPO, celując w 23 mld dolarów i wycenę 65,22 biliona nair; akcje dla inwestorów indywidualnych są dostępne do 13 października.' else seo_description_pl end
where slug = 'dangote-refinery-launches-africas-largest-ipo-targets-23bn-p-wti8hxqj' and status = 'published';
update public.blog_posts set
  title_de = case when title_de is null or btrim(title_de) = '' or title_de = title_en then 'Von Venedig bis Split: Städte bestrafen schlechtes Touristenverhalten' else title_de end,
  excerpt_de = case when excerpt_de is null or btrim(excerpt_de) = '' or excerpt_de = excerpt_en then 'Rekordzahlen von Reisenden strapazieren die Geduld der Gastgeberstädte. Bußgelder, Gebühren und Verbote sind die Antwort, für die sich manche entschieden haben.' else excerpt_de end,
  summary_de = case when summary_de is null or btrim(summary_de) = '' or summary_de = summary_en then 'Touristen unternahmen 2023 1,3 Milliarden grenzüberschreitende Reisen, und die Gegenreaktion ließ nicht auf sich warten. Venedig verlangt inzwischen Eintritt von Tagesausflüglern, Amsterdam hat sein Kreuzfahrtterminal geschlossen, und Dubrovnik hat das Besteigen von Statuen verboten. Bhutan geht den entgegengesetzten Weg und verlangt von jedem Besucher 100 Dollar pro Tag. Die Autorin Paige McClanahan, deren Buch The New Tourist von 2024 den Wandel nachzeichnet, argumentiert, die Lösung sei einfacher als all das.' else summary_de end,
  seo_title_de = case when seo_title_de is null or btrim(seo_title_de) = '' or seo_title_de = seo_title_en then 'Von Venedig bis Split: Städte bestrafen schlechtes Touristenverhalten' else seo_title_de end,
  seo_description_de = case when seo_description_de is null or btrim(seo_description_de) = '' or seo_description_de = seo_description_en then 'Während internationale Reisen auf 1,3 Milliarden pro Jahr steigen, bekämpfen Städte von Venedig bis Dubrovnik den Overtourism mit Bußgeldern, Abgaben und Verboten.' else seo_description_de end,
  title_pl = case when title_pl is null or btrim(title_pl) = '' or title_pl = title_en then 'Od Wenecji po Split: miasta karzą złe zachowanie turystów' else title_pl end,
  excerpt_pl = case when excerpt_pl is null or btrim(excerpt_pl) = '' or excerpt_pl = excerpt_en then 'Rekordowa liczba podróżnych wystawia na próbę cierpliwość miast-gospodarzy. Kary, opłaty i zakazy to odpowiedź, jaką wybrały niektóre z nich.' else excerpt_pl end,
  summary_pl = case when summary_pl is null or btrim(summary_pl) = '' or summary_pl = summary_en then 'W 2023 roku turyści odbyli 1,3 miliarda podróży zagranicznych, a w ślad za tym przyszedł sprzeciw. Wenecja pobiera teraz opłatę od osób przyjeżdżających na jeden dzień, Amsterdam zamknął swój terminal wycieczkowców, a Dubrownik zakazał wspinania się na posągi. Bhutan wybiera podejście odwrotne, pobierając od każdego odwiedzającego 100 dolarów dziennie. Autorka Paige McClanahan, której książka The New Tourist z 2024 roku opisuje tę zmianę, przekonuje, że rozwiązanie jest prostsze niż to wszystko.' else summary_pl end,
  seo_title_pl = case when seo_title_pl is null or btrim(seo_title_pl) = '' or seo_title_pl = seo_title_en then 'Od Wenecji po Split: miasta karzą złe zachowanie turystów' else seo_title_pl end,
  seo_description_pl = case when seo_description_pl is null or btrim(seo_description_pl) = '' or seo_description_pl = seo_description_en then 'Gdy liczba podróży międzynarodowych sięga 1,3 miliarda rocznie, miasta od Wenecji po Dubrownik walczą z nadmierną turystyką za pomocą grzywien, opłat i zakazów.' else seo_description_pl end,
  title_ru = case when title_ru is null or btrim(title_ru) = '' or title_ru = title_en then 'От Венеции до Сплита: города наказывают за плохое поведение туристов' else title_ru end,
  excerpt_ru = case when excerpt_ru is null or btrim(excerpt_ru) = '' or excerpt_ru = excerpt_en then 'Рекордное число путешественников испытывает терпение принимающих городов. Штрафы, сборы и запреты — ответ, который выбрали некоторые из них.' else excerpt_ru end,
  summary_ru = case when summary_ru is null or btrim(summary_ru) = '' or summary_ru = summary_en then 'В 2023 году туристы совершили 1,3 млрд трансграничных поездок, и отторжение не заставило себя ждать. Венеция теперь берёт плату с однодневных гостей, Амстердам закрыл круизный терминал, а Дубровник запретил забираться на статуи. Бутан выбирает противоположный подход и берёт с каждого посетителя 100 долларов в день. Автор Пейдж Макклэнахан, чья книга «The New Tourist» (2024) прослеживает эту перемену, утверждает, что решение проще, чем всё перечисленное.' else summary_ru end,
  seo_title_ru = case when seo_title_ru is null or btrim(seo_title_ru) = '' or seo_title_ru = seo_title_en then 'От Венеции до Сплита: города наказывают за плохое поведение туристов' else seo_title_ru end,
  seo_description_ru = case when seo_description_ru is null or btrim(seo_description_ru) = '' or seo_description_ru = seo_description_en then 'Когда число международных поездок достигает 1,3 млрд в год, города от Венеции до Дубровника борются с избытком туристов штрафами, сборами и запретами.' else seo_description_ru end
where slug = 'from-venice-to-split-cities-are-punishing-bad-tourist-behavi-otky2dky' and status = 'published';
update public.blog_posts set
  title_pl = case when title_pl is null or btrim(title_pl) = '' or title_pl = title_en then 'ArtCargo przynosi na ulice Nikozji 43 bezpłatne występy' else title_pl end,
  excerpt_pl = case when excerpt_pl is null or btrim(excerpt_pl) = '' or excerpt_pl = excerpt_en then 'Dziewięć produkcji, dziewięć krajów i numer na linie przy muzyce rockowej na żywo: plenerowy festiwal ArtCargo zajmie centrum Nikozji od 16 do 25 października, wstęp wolny.' else excerpt_pl end,
  summary_pl = case when summary_pl is null or btrim(summary_pl) = '' or summary_pl = summary_en then 'ArtCargo, plenerowy festiwal sztuk scenicznych, który przyciągnął prawie 40 000 osób podczas debiutanckiej edycji w Limassol, przenosi się do Nikozji od 16 do 25 października z dziewięcioma produkcjami i 43 bezpłatnymi występami, w których wezmą udział artyści z Cypru, Francji, Niemiec, Holandii, Szwecji, Finlandii, Argentyny, Katalonii i Japonii.' else summary_pl end,
  seo_title_pl = case when seo_title_pl is null or btrim(seo_title_pl) = '' or seo_title_pl = seo_title_en then 'Festiwal ArtCargo: 43 bezpłatne występy w Nikozji, 16–25 października' else seo_title_pl end,
  seo_description_pl = case when seo_description_pl is null or btrim(seo_description_pl) = '' or seo_description_pl = seo_description_en then 'ArtCargo wraca z dziewięcioma produkcjami i 43 bezpłatnymi występami plenerowymi w Nikozji od 16 do 25 października, z artystami z dziewięciu krajów, w tym mistrzynią trickline Kanon Ito.' else seo_description_pl end
where slug = 'artcargo-brings-43-free-performances-to-nicosias-streets-tndg8yrn' and status = 'published';
update public.blog_posts set
  title_pl = case when title_pl is null or btrim(title_pl) = '' or title_pl = title_en then 'Serbski malarz otwiera w Nikozji wystawę zbudowaną z jego pierwszych lat na Cyprze' else title_pl end,
  excerpt_pl = case when excerpt_pl is null or btrim(excerpt_pl) = '' or excerpt_pl = excerpt_en then 'Closely Observed to debiutancka wystawa Milenko Stevanović: siedem prac powstałych w latach 2021–2026, pokazanych w galerii In Toto, śledzi jego pierwsze lata na wyspie poprzez portrety i autoportret.' else excerpt_pl end,
  summary_pl = case when summary_pl is null or btrim(summary_pl) = '' or summary_pl = summary_en then 'Serbski artysta Milenko Stevanović prezentuje Closely Observed w galerii In Toto w Nikozji od 17 września do 15 października. Wystawa siedmiu prac, której kuratorem jest Constantinos Kyprianou, a prezentacji podjęło się ABR, obejmuje spotkanie z artystą z udziałem Diomedesa Koufterosa oraz oprowadzanie z Michaelem Pavlidesem.' else summary_pl end,
  seo_title_pl = case when seo_title_pl is null or btrim(seo_title_pl) = '' or seo_title_pl = seo_title_en then 'Wystawa Closely Observed Milenko Stevanović w galerii In Toto w Nikozji' else seo_title_pl end,
  seo_description_pl = case when seo_description_pl is null or btrim(seo_description_pl) = '' or seo_description_pl = seo_description_en then 'Serbski artysta Milenko Stevanović prezentuje siedem prac z lat 2021–2026 na wystawie Closely Observed w galerii In Toto w Nikozji od 17 września do 15 października.' else seo_description_pl end
where slug = 'serbian-painter-opens-nicosia-show-built-from-his-first-year-bs3yuiw0' and status = 'published';
update public.blog_posts set
  title_ru = case when title_ru is null or btrim(title_ru) = '' or title_ru = title_en then 'Шагающая женщина на платформе занимает пустой постамент Лондона' else title_ru end,
  excerpt_ru = case when excerpt_ru is null or btrim(excerpt_ru) = '' or excerpt_ru = excerpt_en then '«Леди в синем» Чабалалы Селф занимает четвёртый постамент на Трафальгарской площади — место, остававшееся пустым почти два столетия после того, как закончились деньги на задуманную статую.' else excerpt_ru end,
  summary_ru = case when summary_ru is null or btrim(summary_ru) = '' or summary_ru = summary_en then 'Американская художница Чабалала Селф представила в сентябре 2026 года свою скульптуру «Леди в синем» на четвёртом постаменте на Трафальгарской площади. Постамент, построенный в 1841 году для конной статуи, на которую так и не нашли средств, с 1999 года принимает временные работы. Работа Селф изображает шагающую женщину на платформе, выполненную в полированных коричневых тонах и в синем цвете, навеянном ляпис-лазурью, с опорой на футуристическую скульптуру и африканское искусство. Выступавшие на открытии призывали поддерживать разнообразие, равенство и терпимость.' else summary_ru end,
  seo_title_ru = case when seo_title_ru is null or btrim(seo_title_ru) = '' or seo_title_ru = seo_title_en then '«Леди в синем» Чабалалы Селф открыта на четвёртом постаменте Лондона' else seo_title_ru end,
  seo_description_ru = case when seo_description_ru is null or btrim(seo_description_ru) = '' or seo_description_ru = seo_description_en then 'Скульптура Чабалалы Селф «Леди в синем» занимает четвёртый постамент на Трафальгарской площади — пьедестал, построенный в 1841 году и пустовавший более века до программы искусства 1999 года.' else seo_description_ru end
where slug = 'a-striding-woman-in-platform-shoes-claims-londons-empty-plin-2b0kqkmx' and status = 'published';
